questionvariables.text:
/* 1 = Cube
   2 = Cuboid
   3 = Cone
   4 = Cylinder
   5 = Regular tetrahedron
   6 = Regular triangular prism
*/

solid_id : rand(6)+1;

/* Number of axes of rotational symmetry */

num_axes :
if solid_id=1 then 13
elseif solid_id=2 then 3
elseif solid_id=3 then 1
elseif solid_id=4 then 1
elseif solid_id=5 then 4
else 4;

/* Name of solid */

solid_name :
if solid_id=1 then "cube"
elseif solid_id=2 then "cuboid"
elseif solid_id=3 then "cone"
elseif solid_id=4 then "cylinder"
elseif solid_id=5 then "regular tetrahedron"
else "regular triangular prism";

/* Teacher answer */

ta : num_axes;
